import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Ring-3 apps - overview","description":"","frontmatter":{},"headers":[],"relativePath":"l1/overview.md","filePath":"l1/overview.md"}'),o={name:"l1/overview.md"};function n(i,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="ring-3-apps-overview" tabindex="-1">Ring-3 apps - overview <a class="header-anchor" href="#ring-3-apps-overview" aria-label="Permalink to &quot;Ring-3 apps - overview&quot;">​</a></h1><p>L0 is a pure service kernel: it finishes boot by launching <code>ush</code>, the ring-3 shell, and every user-visible command is itself a ring-3 program. The whole point of the architecture is that the surface L0 exposes is small, numbered and complete - so apps can exist.</p><h2 id="the-layers" tabindex="-1">The layers <a class="header-anchor" href="#the-layers" aria-label="Permalink to &quot;The layers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1  ush (the boot shell) + 284 registry programs</span></span>
<span class="line"><span>    in ocos/l1apps/&lt;name&gt;/main.c - freestanding C against</span></span>
<span class="line"><span>    ocos/interface/*.h</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>    SYS_L1SVC(cat, op, arg, out, cap)   20 categories, ~245 ops</span></span>
<span class="line"><span>    SYS_* (open/read/write/fork/execve/wait4/readline/getch/...)</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>L0  Open Cube OS service kernel</span></span>
<span class="line"><span>    (ocos/kernel + ocos/services + ocos/drivers)</span></span></code></pre></div><h2 id="where-the-surface-lives" tabindex="-1">Where the surface lives <a class="header-anchor" href="#where-the-surface-lives" aria-label="Permalink to &quot;Where the surface lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header (ocos/interface/)</th><th>What it covers</th></tr></thead><tbody><tr><td><code>l1_api_syscall.h</code></td><td>syscall wrappers, string/IO helpers, <code>l1svc_main()</code> - the verbatim wrapper body</td></tr><tr><td><code>l1_svc_ops.h</code></td><td>the category/op numbering contract (auto-mirrored from the L0 header)</td></tr><tr><td><code>l1_i18n_api.h</code></td><td><code>tr_()</code> + the per-app bilingual tables</td></tr><tr><td><code>l1_wizard_api.h</code></td><td>the shared wizard primitives (menus, asks, confirms, anchor probes)</td></tr><tr><td><code>l1_fs_api.h</code></td><td>path helpers shared by the file tools</td></tr><tr><td><code>l1_editor_core.h</code></td><td>the editor engine behind <code>edit</code> and the TUI editor</td></tr><tr><td><code>l1_i18n_res.h</code></td><td>the shared <code>MSG_ID</code> system-message numbering (L0/L1 common)</td></tr><tr><td><code>l1_diag_cmds.h</code></td><td>the shared <code>dev</code>/<code>drv</code> diag command layer</td></tr><tr><td><code>l1_api_surface.h</code></td><td>the umbrella: the audit point for &quot;what L1 can see&quot;</td></tr><tr><td><code>l1_crt_entry.asm</code></td><td>the linked (not included) <code>_start</code> trampoline</td></tr></tbody></table><p>The service-side declarations live in <code>ocos/services/*/interface/</code> (one folder per facet); the numbering mirror regenerates with <code>tools/gen_l1svc_ops.py</code>.</p><h2 id="the-counts-that-matter" tabindex="-1">The counts that matter <a class="header-anchor" href="#the-counts-that-matter" aria-label="Permalink to &quot;The counts that matter&quot;">​</a></h2><ul><li><strong>284 registry programs</strong> - 276 historical commands (the interface-freeze floor; commands are added, never removed) plus the 8 merged mega-apps.</li><li><strong>20 L1SVC categories</strong> (time/block/nic/snd/power/ota/fs/net/ health/klog/watchdog/crypto/l1/display/input/camera/usb/ocire/ diag/tui), ~245 numbered ops.</li><li>Every program ships <code>i18n/{en,zh}.json</code> - the build fails on a missing resource (a program without translations is a delivery violation, not a warning).</li></ul><h2 id="how-a-command-runs" tabindex="-1">How a command runs <a class="header-anchor" href="#how-a-command-runs" aria-label="Permalink to &quot;How a command runs&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool lsblk</span></span>
<span class="line"><span>  ush forks; child execve(&quot;disk-tool&quot;, [&quot;disk-tool&quot;,&quot;lsblk&quot;])</span></span>
<span class="line"><span>  app_main(argc, argv) sees argv[1] = &quot;lsblk&quot;</span></span>
<span class="line"><span>  -&gt; classic dispatch: table lookup -&gt; sys_l1svc(BLOCK, LSBLK, ...)</span></span>
<span class="line"><span>  -&gt; service output printed verbatim</span></span>
<span class="line"><span>  ush wait4()s the child, prints the next prompt</span></span></code></pre></div><p>The historical single commands are the same mechanism one level simpler: <code>lsblk/main.c</code> is <code>l1svc_main(argc, argv, CAT, OP)</code> - the v2.2.0 ush SVC runner semantics, byte for byte.</p><h2 id="walk-through-order" tabindex="-1">Walk-through order <a class="header-anchor" href="#walk-through-order" aria-label="Permalink to &quot;Walk-through order&quot;">​</a></h2><ol><li>This page.</li><li><a href="./surface-map.html">surface-map.md</a> - the categories/ops by group.</li><li><a href="./app-anatomy.html">app-anatomy</a> - what a main.c is made of.</li><li><a href="./writing-apps.html">writing-apps</a> - a complete app, source to <code>run</code>.</li><li>The family pages: drivers, OTA, loader, TUI, watchdog/health.</li></ol>`,14)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
